cat > /workspace/submission/infer.py <<'PYEOF'
"""Exact inference over the set F of all minimum-fault explanations.

Compilation
-----------
Each snapshot contributes an integer program over its demand vector: a link
load is the integer linear form ``Z = coeffs . q`` scaled by the least common
denominator of the edge's rational route contributions, so capacities and
observation intervals are plain integer constraints.  Trusted observations
are hard constraints of that program.

The incident couples snapshots through one free boolean ``f_d`` per observed
domain (``f_d`` = "domain d is blamed") with the single implication

    not f_d  ->  every observation of d is satisfied,

together with the fault budget ``#blamed <= max_faults``.  Writing k for the
least attainable fault count, the set F of optimal explanations is exactly the
projection of ``base AND #blamed <= k`` onto the demand variables, and the
*optimal blame patterns* (the distinct fault sets realized by explanations in
F) are enumerated from that one program.

Each snapshot's part of F is the union, over optimal blame patterns D, of

    Sol_s(domains \\ D)

where ``Sol_s(R)`` is the snapshot program with all observations of the
domains in R additionally required.  (A requirement set that is infeasible for
that very snapshot contributes an empty set, so the all-snapshot patterns are
enough.)  Those per-snapshot programs hold no fault booleans at all, which
keeps the many interval queries cheap.  If the optimal blame patterns are too
numerous to enumerate, inference falls back to the single all-snapshot
program, which is slower but equally exact.
"""

import z3
from fractions import Fraction

# Decompose only when the optimal blame patterns are few enough to enumerate.
PATTERN_CAP = 24


class Infeasible(Exception):
    """No feasible explanation exists for the incident."""


def _lin(terms, ctx):
    """Integer linear expression built from coefficient*variable terms."""
    if not terms:
        return z3.IntVal(0, ctx=ctx)
    if len(terms) == 1:
        return terms[0]
    return z3.Sum(terms)


def _rat(value):
    """Exact reduced 'numerator/denominator' string of a Fraction."""
    return '%d/%d' % (value.numerator, value.denominator)


def _solve(sol, extra=()):
    """Model of the solver's constraints plus extras, or None if unsat."""
    sol.push()
    if extra:
        sol.add(*extra)
    res = sol.check()
    model = sol.model() if res == z3.sat else None
    sol.pop()
    if res == z3.unknown:
        raise RuntimeError('z3 returned unknown')
    return model


def _minimize(sol, expr, low, cur):
    """Least value of expr given a valid lower bound and an attained value."""
    if cur <= low:
        return cur
    if _solve(sol, [expr <= low]) is not None:
        return low
    best = cur
    lo = low + 1
    while lo < best:
        mid = (lo + best) // 2
        model = _solve(sol, [expr <= mid])
        if model is not None:
            value = model.eval(expr, model_completion=True).as_long()
            if value < best:
                best = value
        else:
            lo = mid + 1
    return best


def _maximize(sol, expr, high, cur):
    """Greatest value of expr given a valid upper bound and an attained value."""
    if cur >= high:
        return cur
    if _solve(sol, [expr >= high]) is not None:
        return high
    best = cur
    hi = high - 1
    while hi > best:
        mid = (best + hi + 1) // 2
        model = _solve(sol, [expr >= mid])
        if model is not None:
            value = model.eval(expr, model_completion=True).as_long()
            if value > best:
                best = value
        else:
            hi = mid - 1
    return best


class _Snapshot(object):
    """Variables and integer constraints describing one snapshot.

    ``base`` holds the demand box, the capacity limits and the trusted
    observations; ``dom_obs`` maps a domain to the satisfaction formulas of
    its observations, which a caller may add as requirements.
    """

    def __init__(self, inst, si, ctx, prefix):
        self.inst = inst
        self.si = si
        self.C = len(inst.commodities)
        self.E = len(inst.edges)
        self.q = [z3.Int('%sq!%d!%d' % (prefix, si, c), ctx=ctx)
                  for c in range(self.C)]
        self.link = []
        self.ingress = {}
        self.egress = {}
        cons = []
        bounds = inst.snapshots[si].bounds
        for c in range(self.C):
            cons.append(self.q[c] >= bounds[c][0])
            cons.append(self.q[c] <= bounds[c][1])
        for ei in range(self.E):
            scale, coeffs = inst.edge_coeff[ei]
            terms = [coeffs[c] * self.q[c] for c in range(self.C) if coeffs[c]]
            expr = _lin(terms, ctx)
            self.link.append(expr)
            if terms:
                cons.append(expr <= scale * inst.edges[ei].capacity)
        for node in inst.nodes:
            iidx = inst.ingress_indices[node]
            if iidx:
                self.ingress[node] = _lin([self.q[c] for c in iidx], ctx)
            eidx = inst.egress_indices[node]
            if eidx:
                self.egress[node] = _lin([self.q[c] for c in eidx], ctx)
        self.dom_obs = {}
        self.obs_specs = []   # (domain or None, satisfied, violated)
        for obs in inst.snapshots[si].observations:
            if obs.metric == 'demand':
                expr = self.q[inst.commodity_index[obs.target]]
                lo, hi = obs.lower, obs.upper
            elif obs.metric == 'link':
                ei = inst.edge_index[obs.target]
                scale = inst.edge_coeff[ei][0]
                expr = self.link[ei]
                lo, hi = scale * obs.lower, scale * obs.upper
            elif obs.metric == 'ingress':
                expr = self.ingress.get(obs.target, z3.IntVal(0, ctx=ctx))
                lo, hi = obs.lower, obs.upper
            else:
                expr = self.egress.get(obs.target, z3.IntVal(0, ctx=ctx))
                lo, hi = obs.lower, obs.upper
            satisfied = z3.And(expr >= lo, expr <= hi)
            violated = z3.Or(expr < lo, expr > hi)
            self.obs_specs.append((obs.domain, satisfied, violated))
            if obs.domain is None:
                cons.append(satisfied)
            else:
                self.dom_obs.setdefault(obs.domain, []).append(satisfied)
        self.base = cons


class _Engine(object):
    """Answers every query about the set F of optimal explanations."""

    def __init__(self, inst):
        self.inst = inst
        self.S = len(inst.snapshots)
        self.C = len(inst.commodities)
        self.E = len(inst.edges)
        self.ctx = z3.Context()
        self.snaps = [_Snapshot(inst, si, self.ctx, '') for si in range(self.S)]
        self.fault_domains = inst.observed_domains()
        self.f = {}
        for domain in self.fault_domains:
            self.f[domain] = z3.Bool('f!%d' % inst.domain_index[domain], ctx=self.ctx)
        self.fvars = [self.f[d] for d in self.fault_domains]
        cons = []
        for snap in self.snaps:
            cons.extend(snap.base)
            for domain, sats in snap.dom_obs.items():
                blame = self.f[domain]
                for sat in sats:
                    cons.append(z3.Or(blame, sat))
        self.sol = z3.Solver(ctx=self.ctx)
        self.sol.add(cons)
        self.k = None
        self.domain_violated = {}
        self.domain_satisfied = {}
        for domain in self.fault_domains:
            viols = []
            sats = []
            for snap in self.snaps:
                for dom, sat, viol in snap.obs_specs:
                    if dom == domain:
                        viols.append(viol)
                        sats.append(sat)
            self.domain_violated[domain] = viols[0] if len(viols) == 1 else z3.Or(viols)
            self.domain_satisfied[domain] = sats[0] if len(sats) == 1 else z3.And(sats)

    # ------------------------------------------------------------- helpers

    def _budget(self, count):
        if not self.fvars or count >= len(self.fvars):
            return z3.BoolVal(True, ctx=self.ctx)
        return z3.PbLe([(f, 1) for f in self.fvars], count)

    def _actual_faults(self, demands, loads):
        """Actual faulty-domain set of one explanation (exact recheck)."""
        inst = self.inst
        faulty = set()
        for i, snap in enumerate(inst.snapshots):
            for obs in snap.observations:
                if not (obs.lower <= inst.true_value(obs, demands[i], loads[i])
                        <= obs.upper):
                    faulty.add(obs.domain)
        return faulty

    def _witness(self, demands, loads, faulty):
        return {
            'demands': [[v for v in row] for row in demands],
            'links': [[_rat(v) for v in row] for row in loads],
            'faults': sorted(faulty),
        }

    # ----------------------------------------------------------------- run

    def run(self):
        inst = self.inst
        if _solve(self.sol, [self._budget(inst.max_faults)]) is None:
            raise Infeasible()
        lo, hi = 0, inst.max_faults
        while lo < hi:
            mid = (lo + hi) // 2
            if _solve(self.sol, [self._budget(mid)]) is not None:
                hi = mid
            else:
                lo = mid + 1
        self.k = lo
        self.sol.add(self._budget(self.k))
        patterns = self._patterns()
        if patterns is not None:
            body = self._decomposed(patterns)
            if body is not None:
                return body
        return self._full()

    def _patterns(self):
        """All optimal blame patterns, or None when there are too many.

        Under the budget ``#blamed <= k`` every model blames exactly its
        actual fault set, so solving and blocking repeatedly enumerates the
        fault sets realized by F.
        """
        if not self.fvars:
            return [frozenset()]
        sol = self.sol
        sol.push()
        found = []
        while len(found) <= PATTERN_CAP:
            model = _solve(sol)
            if model is None:
                sol.pop()
                return found
            blamed = frozenset(d for d in self.fault_domains
                               if model.eval(self.f[d], model_completion=True))
            found.append(blamed)
            lits = [self.f[d] if d in blamed else z3.Not(self.f[d])
                    for d in self.fault_domains]
            sol.add(z3.Not(z3.And(lits)))
        sol.pop()
        return None

    # -------------------------------------------------------- decomposition

    def _decomposed(self, patterns):
        """Inference over per-snapshot programs; None triggers the fallback."""
        inst = self.inst
        S, C, E = self.S, self.C, self.E
        k = self.k
        ncom = len(patterns)
        all_domains = frozenset(self.fault_domains)
        requirements = [all_domains - pattern for pattern in patterns]

        # Distinct requirement scopes per snapshot, and one solver each.
        ctx = z3.Context()
        scope_snapshot = []      # snapshot index of each scope
        scope_solvers = []       # (snapshot program, solver) of each scope
        scope_models = []        # a model of each scope
        scope_of = []            # pattern -> snapshot -> scope index
        keys = {}
        for req in requirements:
            per_snap = []
            for si in range(S):
                snap = self.snaps[si]
                sig = tuple(sorted(d for d in req if snap.dom_obs.get(d)))
                index = keys.get((si, sig))
                if index is None:
                    formulas = []
                    for d in req:
                        formulas.extend(snap.dom_obs.get(d, ()))
                    local = _Snapshot(inst, si, ctx, 's')
                    solver = z3.Solver(ctx=ctx)
                    solver.add(local.base)
                    if formulas:
                        solver.add(formulas)
                    model = _solve(solver)
                    if model is None:
                        return None
                    index = len(scope_snapshot)
                    keys[(si, sig)] = index
                    scope_snapshot.append(si)
                    scope_solvers.append((local, solver))
                    scope_models.append(model)
            per_snap.append(keys[(si, sig)])
            scope_of.append(per_snap)

        def scope_indices(si):
            return [j for j in range(len(scope_snapshot)) if scope_snapshot[j] == si]

        def scope_demands(index):
            local = scope_solvers[index][0]
            return [scope_models[index].eval(v, model_completion=True).as_long()
                    for v in local.q]

        # Demand ranges over the union of scopes.
        dmin = [[None] * C for _ in range(S)]
        dmax = [[None] * C for _ in range(S)]
        dmin_at = [[None] * C for _ in range(S)]
        dmax_at = [[None] * C for _ in range(S)]
        for si in range(S):
            bounds = inst.snapshots[si].bounds
            indices = scope_indices(si)
            values = {j: scope_demands(j) for j in indices}
            for ci in range(C):
                low, high = bounds[ci]
                best_min = min(values[j][ci] for j in indices)
                best_max = max(values[j][ci] for j in indices)
                argmin = min(indices, key=lambda j: values[j][ci])
                argmax = max(indices, key=lambda j: values[j][ci])
                if best_min > low:
                    for j in indices:
                        local, solver = scope_solvers[j]
                        value = _minimize(solver, local.q[ci], low, values[j][ci])
                        if value < best_min:
                            best_min = value
                            argmin = j
                            if best_min == low:
                                break
                if best_max < high:
                    for j in indices:
                        local, solver = scope_solvers[j]
                        value = _maximize(solver, local.q[ci], high, values[j][ci])
                        if value > best_max:
                            best_max = value
                            argmax = j
                            if best_max == high:
                                break
                dmin[si][ci] = best_min
                dmax[si][ci] = best_max
                dmin_at[si][ci] = argmin
                dmax_at[si][ci] = argmax

        # Link load ranges over the union of scopes.
        lmin = [[None] * E for _ in range(S)]
        lmax = [[None] * E for _ in range(S)]
        for si in range(S):
            bounds = inst.snapshots[si].bounds
            los = [b[0] for b in bounds]
            his = [b[1] for b in bounds]
            for j in scope_indices(si):
                local, solver = scope_solvers[j]
                demands = scope_demands(j)
                cache = {}
                for ei in range(E):
                    scale, coeffs = inst.edge_coeff[ei]
                    if not any(coeffs):
                        mn = mx = 0
                    else:
                        sig = (scale, tuple(coeffs),
                               scale * inst.edges[ei].capacity)
                        if sig in cache:
                            mn, mx = cache[sig]
                        else:
                            zlb = 0
                            zub = scale * inst.edges[ei].capacity
                            for ci in range(C):
                                if coeffs[ci]:
                                    zlb += coeffs[ci] * los[ci]
                                    zub += coeffs[ci] * his[ci]
                            if zlb > zub:
                                zlb = zub
                            cur = 0
                            for ci in range(C):
                                if coeffs[ci]:
                                    cur += coeffs[ci] * demands[ci]
                            if zlb == zub:
                                mn = mx = zlb
                            else:
                                mn = _minimize(solver, local.link[ei], zlb, cur)
                                mx = _maximize(solver, local.link[ei], zub, cur)
                            cache[sig] = (mn, mx)
                    if lmin[si][ei] is None or mn < lmin[si][ei]:
                        lmin[si][ei] = mn
                    if lmax[si][ei] is None or mx > lmax[si][ei]:
                        lmax[si][ei] = mx

        # Controller verdicts.
        verdicts = []
        for si in range(S):
            snap_data = inst.snapshots[si]
            some_agree = False
            some_disagree = False
            for j in scope_indices(si):
                local, solver = scope_solvers[j]
                agree = []
                disagree = []
                for ci in range(C):
                    c = snap_data.controller[ci]
                    t = snap_data.tolerance
                    agree.append(local.q[ci] >= c - t)
                    agree.append(local.q[ci] <= c + t)
                    disagree.append(z3.Or(local.q[ci] < c - t,
                                          local.q[ci] > c + t))
                if C == 0:
                    some_agree = True
                elif not some_agree and _solve(solver, agree) is not None:
                    some_agree = True
                if C > 0 and not some_disagree:
                    if _solve(solver, [z3.Or(disagree)]) is not None:
                        some_disagree = True
            if some_agree:
                verdicts.append('consistent' if not some_disagree
                                else 'undetermined')
            else:
                verdicts.append('inconsistent')

        # Witness from the first pattern.
        witness_demands = []
        witness_loads = []
        for si in range(S):
            j = scope_of[0][si]
            witness_demands.append(scope_demands(j))
            witness_loads.append(inst.edge_loads(witness_demands[-1]))
        faulty = self._actual_faults(witness_demands, witness_loads)
        if faulty != patterns[0] or len(faulty) != k:
            return None
        witness = self._witness(witness_demands, witness_loads, faulty)

        unique = all(dmin[i][ci] == dmax[i][ci]
                     for i in range(S) for ci in range(C))

        # A second explanation whose demand matrix differs, when ambiguous.
        alternative = None
        if not unique:
            for i in range(S):
                for ci in range(C):
                    if dmin[i][ci] == dmax[i][ci]:
                        continue
                    if witness_demands[i][ci] != dmin[i][ci]:
                        target, scope = dmin[i][ci], dmin_at[i][ci]
                    else:
                        target, scope = dmax[i][ci], dmax_at[i][ci]
                    chosen = None
                    for pi in range(ncom):
                        if scope_of[pi][i] == scope:
                            chosen = pi
                            break
                    if chosen is None:
                        return None
                    local, solver = scope_solvers[scope]
                    model = _solve(solver, [local.q[ci] == target])
                    if model is None:
                        return None
                    alt_demands = [None] * S
                    alt_demands[i] = [model.eval(v, model_completion=True).as_long()
                                      for v in local.q]
                    for j in range(S):
                        if j == i:
                            continue
                        alt_demands[j] = scope_demands(scope_of[chosen][j])
                    alt_loads = [inst.edge_loads(row) for row in alt_demands]
                    alt_faults = self._actual_faults(alt_demands, alt_loads)
                    if alt_faults != patterns[chosen] or len(alt_faults) != k:
                        return None
                    if alt_demands == witness_demands:
                        return None
                    alternative = self._witness(alt_demands, alt_loads, alt_faults)
                    break
                if alternative is not None:
                    break

        forced = set(patterns[0])
        possible = set(patterns[0])
        for pattern in patterns[1:]:
            forced &= pattern
            possible |= pattern

        snapshots = []
        for i in range(S):
            scale_of = [inst.edge_coeff[ei][0] for ei in range(E)]
            snapshots.append({
                'id': inst.snapshots[i].id,
                'demands': [[dmin[i][ci], dmax[i][ci]] for ci in range(C)],
                'links': [[_rat(Fraction(lmin[i][ei], scale_of[ei])),
                           _rat(Fraction(lmax[i][ei], scale_of[ei]))]
                          for ei in range(E)],
                'verdict': verdicts[i],
            })
        return {
            'status': 'unique' if unique else 'ambiguous',
            'min_faults': k,
            'faults': {'forced': sorted(forced), 'possible': sorted(possible)},
            'snapshots': snapshots,
            'witness': witness,
            'alternative': alternative,
        }

    # ---------------------------------------------------------- full program

    def _full(self):
        """Inference from the single all-snapshot program (always exact)."""
        inst = self.inst
        S, C, E = self.S, self.C, self.E
        sol = self.sol

        model = _solve(sol)
        demands = [[model.eval(var, model_completion=True).as_long()
                    for var in snap.q] for snap in self.snaps]
        loads = [inst.edge_loads(demands[i]) for i in range(S)]
        faulty = self._actual_faults(demands, loads)
        if len(faulty) != self.k:
            raise RuntimeError('witness fault count mismatch')
        witness = self._witness(demands, loads, faulty)

        dmin = [[None] * C for _ in range(S)]
        dmax = [[None] * C for _ in range(S)]
        for i in range(S):
            bounds = inst.snapshots[i].bounds
            for ci in range(C):
                lo, hi = bounds[ci]
                cur = demands[i][ci]
                dmin[i][ci] = _minimize(sol, self.snaps[i].q[ci], lo, cur)
                dmax[i][ci] = _maximize(sol, self.snaps[i].q[ci], hi, cur)

        lmin = [[None] * E for _ in range(S)]
        lmax = [[None] * E for _ in range(S)]
        for i in range(S):
            bounds = inst.snapshots[i].bounds
            los = [b[0] for b in bounds]
            his = [b[1] for b in bounds]
            snap = self.snaps[i]
            cache = {}
            for ei in range(E):
                scale, coeffs = inst.edge_coeff[ei]
                if not any(coeffs):
                    lmin[i][ei] = lmax[i][ei] = 0
                    continue
                sig = (scale, tuple(coeffs), scale * inst.edges[ei].capacity)
                if sig in cache:
                    mn, mx = cache[sig]
                else:
                    zlb = 0
                    zub = scale * inst.edges[ei].capacity
                    for ci in range(C):
                        if coeffs[ci]:
                            zlb += coeffs[ci] * los[ci]
                            zub += coeffs[ci] * his[ci]
                    if zlb > zub:
                        zlb = zub
                    cur = 0
                    for ci in range(C):
                        if coeffs[ci]:
                            cur += coeffs[ci] * demands[i][ci]
                    if zlb == zub:
                        mn = mx = zlb
                    else:
                        mn = _minimize(sol, snap.link[ei], zlb, cur)
                        mx = _maximize(sol, snap.link[ei], zub, cur)
                    cache[sig] = (mn, mx)
                lmin[i][ei] = mn
                lmax[i][ei] = mx

        forced = []
        possible = []
        for domain in self.fault_domains:
            if _solve(sol, [self.domain_violated[domain]]) is not None:
                possible.append(domain)
                if _solve(sol, [self.domain_satisfied[domain]]) is None:
                    forced.append(domain)

        verdicts = []
        for i in range(S):
            snap_data = inst.snapshots[i]
            snap = self.snaps[i]
            agree = []
            disagree = []
            for ci in range(C):
                c = snap_data.controller[ci]
                t = snap_data.tolerance
                agree.append(snap.q[ci] >= c - t)
                agree.append(snap.q[ci] <= c + t)
                disagree.append(z3.Or(snap.q[ci] < c - t, snap.q[ci] > c + t))
            some_agree = C == 0 or _solve(sol, agree) is not None
            some_disagree = C > 0 and _solve(sol, [z3.Or(disagree)]) is not None
            if some_agree:
                verdicts.append('consistent' if not some_disagree
                                else 'undetermined')
            else:
                verdicts.append('inconsistent')

        unique = all(dmin[i][ci] == dmax[i][ci]
                     for i in range(S) for ci in range(C))

        alternative = None
        if not unique:
            for i in range(S):
                for ci in range(C):
                    if dmin[i][ci] == dmax[i][ci]:
                        continue
                    target = dmin[i][ci] if demands[i][ci] != dmin[i][ci] \
                        else dmax[i][ci]
                    model = _solve(sol, [self.snaps[i].q[ci] == target])
                    if model is None:
                        raise RuntimeError('range endpoint not attained')
                    alt_demands = [[model.eval(var, model_completion=True).as_long()
                                    for var in snap.q] for snap in self.snaps]
                    alt_loads = [inst.edge_loads(row) for row in alt_demands]
                    alt_faults = self._actual_faults(alt_demands, alt_loads)
                    if len(alt_faults) != self.k:
                        raise RuntimeError('alternative fault count mismatch')
                    alternative = self._witness(alt_demands, alt_loads, alt_faults)
                    break
                if alternative is not None:
                    break

        snapshots = []
        for i in range(S):
            scale_of = [inst.edge_coeff[ei][0] for ei in range(E)]
            snapshots.append({
                'id': inst.snapshots[i].id,
                'demands': [[dmin[i][ci], dmax[i][ci]] for ci in range(C)],
                'links': [[_rat(Fraction(lmin[i][ei], scale_of[ei])),
                           _rat(Fraction(lmax[i][ei], scale_of[ei]))]
                          for ei in range(E)],
                'verdict': verdicts[i],
            })
        return {
            'status': 'unique' if unique else 'ambiguous',
            'min_faults': self.k,
            'faults': {'forced': sorted(forced), 'possible': sorted(possible)},
            'snapshots': snapshots,
            'witness': witness,
            'alternative': alternative,
        }


def analyze(inst):
    """Full analysis of a validated instance; returns the response body."""
    engine = _Engine(inst)
    try:
        return engine.run()
    finally:
        engine.ctx = None
